  (2, 'kos-putri-eksklusif-dekat-kampus-beji-depok', 'tayang', true, 'kos', 'Disewa', 'Kos Putri Eksklusif dekat Kampus', 'Beji, Depok', 'Depok', 1600000, 'Rp 1,6 jt', '/bulan', 0, 12, 1, '—', '12 m² / kamar', '1', '1 (dalam)', 'SHM', -6.372, 106.818, array['/assets/b9ac1f72724b3b478d6fb25cb7a837e4.jpg', '/assets/faa0a2718e3177e736a593984b61bcad.jpg', '/assets/8d7a27adf3d9572d000675c6d2b4113e.jpg']::text[], array['Kos khusus putri dengan kamar luas, bersih, dan sudah full furnished: kasur, lemari, meja kerja, dan AC. Cocok untuk mahasiswi maupun karyawati yang menginginkan hunian nyaman dan aman.', 'Lokasi strategis, hanya beberapa menit ke kampus dan stasiun. Tersedia Wi-Fi cepat, layanan laundry, CCTV 24 jam, dan penjaga kos. Harga sewa sudah termasuk listrik dan air.']::text[], array['AC', 'Wi-Fi', 'Laundry']::text[], '{"kmOut":0,"pay":"","build":"ready","reno":false,"facing":"Timur","floors":0,"ipl":null,"avail":[],"sec":["cctv"],"fac":["ibadah","minimarket"],"near":["5 km","20 km","1,5 km","45 km"],"walk":3,"lv":"verified","pbb":"Lunas 2026","imb":"Ada (IMB)","isNew":false,"dev":""}'::jsonb),
  (3, 'apartemen-2br-view-kota-kuningan-jakarta-selatan', 'tayang', true, 'apartemen', 'Dijual', 'Apartemen 2BR View Kota', 'Kuningan, Jakarta Selatan', 'Jakarta Selatan', 1200000000, 'Rp 1,2 M', '', 0, 56, 2, '—', '56 m²', '2', '1', 'Strata', -6.229, 106.83, array['/assets/48a0c6593a8eb95a0e54c71d29f7ac5b.jpg', '/assets/a797bc56b381b796263a2b0f1fa0f874.jpg', '/assets/1e906c61051aeefbecc56d6a933ff29d.jpg']::text[], array['Unit apartemen dua kamar tidur di menara premium dengan pemandangan kota yang luas. Tata ruang efisien dengan ruang tamu terbuka dan dapur bersih yang siap pakai.', 'Penghuni menikmati fasilitas kolam renang, gym, taman bermain, dan keamanan 24 jam. Lokasi di pusat bisnis, dekat perkantoran, pusat belanja, dan transportasi umum.']::text[], array['Kolam renang', 'Gym', 'Keamanan 24 jam']::text[], '{"unitType":"2 BR","pay":"kpr","build":"ready","reno":false,"facing":"Barat","floors":0,"ipl":["bayar","Rp 25.000 / m² / bulan",""],"avail":["balkon"],"sec":["onegate","cctv","security"],"fac":["gym","pool","clubhouse","jogging","ibadah","playground","minimarket","parkir"],"near":["1 km","2 km","1,5 km","25 km"],"walk":3,"lv":"verified","pbb":"Lunas 2026","imb":"Ada (PBG)","isNew":false,"dev":""}'::jsonb),
  (4, 'tanah-kavling-siap-bangun-sentul-bogor', 'tayang', true, 'tanah', 'Dijual', 'Tanah Kavling Siap Bangun', 'Sentul, Bogor', 'Bogor', 1050000000, 'Rp 3,5 jt', '/m²', 300, 0, 0, '300 m²', '—', '—', '—', 'SHM', -6.56, 106.857, array['/assets/f2d1559edcb7df1b8ac62392ce2fb5b8.jpg', '/assets/cb60516055ec3117e187d22c75161758.jpg', '/assets/c8508652e2a1649eaab830823a42a563.jpg']::text[], array['Tanah kavling siap bangun di kawasan perumahan yang berkembang pesat. Kontur rata, bentuk tanah ideal, dan sudah bersertifikat SHM sehingga aman untuk investasi maupun hunian.', 'Akses jalan lebar muat dua mobil, listrik dan air sudah tersedia di depan lokasi. Lingkungan hijau dengan udara sejuk, dekat gerbang tol dan fasilitas umum.']::text[], array['SHM', 'Akses 2 mobil', 'Listrik siap']::text[], '{"road":false,"pay":"cash","build":"","reno":false,"facing":"Selatan","floors":0,"ipl":null,"avail":[],"sec":["onegate","cctv","security"],"fac":["jogging","ibadah","minimarket"],"near":["2 km","8 km","4 km","50 km"],"walk":1,"lv":"proses","pbb":"Lunas 2026","imb":"Tidak diperlukan (tanah kosong)","isNew":true,"dev":"Terverifikasi agen Vinmel"}'::jsonb),
  (5, 'rumah-asri-dekat-stasiun-citayam-depok', 'tayang', true, 'rumah', 'Dijual', 'Rumah Asri Dekat Stasiun', 'Citayam, Depok', 'Depok', 890000000, 'Rp 890 jt', '', 90, 70, 2, '90 m²', '70 m²', '2', '1', 'SHM', -6.448, 106.802, array['/assets/0015fe3ee9f7d9fae5966c1354805c8c.jpg', '/assets/83c967883699f4f4515045d52e7d9128.jpg', '/assets/a3d3de7f4f80512034b449f86313effd.jpg']::text[], array['Rumah asri dengan desain modern di lingkungan yang nyaman untuk keluarga muda. Hanya beberapa menit berjalan kaki ke stasiun sehingga sangat praktis untuk aktivitas harian.', 'Terdiri dari dua kamar tidur, satu kamar mandi, ruang keluarga, dapur, dan carport. Bangunan terawat dan siap huni, cocok sebagai rumah pertama.']::text[], array['Carport', 'Dekat stasiun']::text[], '{"pay":"kpr","build":"ready","reno":true,"facing":"Timur","floors":1,"ipl":null,"avail":["taman","garasi"],"sec":["cctv"],"fac":["ibadah","minimarket"],"near":["8 km","25 km","3 km","50 km"],"walk":3,"lv":"verified","pbb":"Lunas 2026","imb":"Ada (IMB)","isNew":false,"dev":""}'::jsonb),
  (6, 'kos-campur-strategis-setiabudi-jakarta-selatan', 'tayang', true, 'kos', 'Disewa', 'Kos Campur Strategis', 'Setiabudi, Jakarta Selatan', 'Jakarta Selatan', 2400000, 'Rp 2,4 jt', '/bulan', 0, 15, 1, '—', '15 m² / kamar', '1', '1 (dalam)', 'SHM', -6.212, 106.832, array['/assets/faa0a2718e3177e736a593984b61bcad.jpg', '/assets/8d7a27adf3d9572d000675c6d2b4113e.jpg', '/assets/b9ac1f72724b3b478d6fb25cb7a837e4.jpg']::text[], array['Kos campur dengan kamar yang lega dan sudah furnished di lokasi super strategis tengah kota. Setiap kamar dilengkapi kamar mandi dalam, AC, kasur, lemari, dan meja.', 'Tersedia dapur bersama, area santai, parkir motor, dan akses kartu untuk keamanan. Dekat perkantoran, kuliner, dan transportasi umum.']::text[], array['Furnished', 'Dapur bersama', 'Parkir motor']::text[], '{"kmOut":0,"pay":"","build":"ready","reno":false,"facing":"Selatan","floors":0,"ipl":null,"avail":[],"sec":["onegate","cctv","security"],"fac":["ibadah","minimarket","parkir"],"near":["1 km","1 km","1 km","30 km"],"walk":3,"lv":"verified","pbb":"Lunas 2026","imb":"Ada (PBG)","isNew":false,"dev":""}'::jsonb),
  (7, 'studio-furnished-dekat-mal-bsd-tangerang', 'tayang', true, 'apartemen', 'Disewa', 'Studio Furnished dekat Mal', 'BSD, Tangerang', 'Tangerang', 4500000, 'Rp 4,5 jt', '/bulan', 0, 24, 1, '—', '24 m²', 'Studio', '1', 'Strata', -6.301, 106.652, array['/assets/a797bc56b381b796263a2b0f1fa0f874.jpg', '/assets/1e906c61051aeefbecc56d6a933ff29d.jpg', '/assets/48a0c6593a8eb95a0e54c71d29f7ac5b.jpg']::text[], array['Unit studio furnished yang praktis dan siap huni, ideal untuk profesional muda. Interior modern lengkap dengan tempat tidur, sofa, pantry, dan perabot penting lainnya.', 'Apartemen terhubung langsung dengan pusat perbelanjaan dan dekat area perkantoran. Fasilitas kolam renang, gym, dan keamanan 24 jam.']::text[], array['Furnished', 'Kolam renang', 'Akses mal']::text[], '{"unitType":"Studio","pay":"","build":"ready","reno":false,"facing":"Timur","floors":0,"ipl":["bayar","Rp 750.000 / bulan",""],"avail":["balkon"],"sec":["onegate","cctv","security"],"fac":["gym","pool","minimarket","parkir"],"near":["2 km","5 km","2 km","35 km"],"walk":3,"lv":"verified","pbb":"Lunas 2026","imb":"Ada (PBG)","isNew":false,"dev":""}'::jsonb),
  (8, 'tanah-pinggir-jalan-raya-cibubur-jakarta-timur', 'tayang', true, 'tanah', 'Dijual', 'Tanah Pinggir Jalan Raya', 'Cibubur, Jakarta Timur', 'Jakarta Timur', 2100000000, 'Rp 2,1 M', '', 500, 0, 0, '500 m²', '—', '—', '—', 'SHM', -6.37, 106.893, array['/assets/c8508652e2a1649eaab830823a42a563.jpg', '/assets/f2d1559edcb7df1b8ac62392ce2fb5b8.jpg', '/assets/cb60516055ec3117e187d22c75161758.jpg']::text[], array['Tanah seluas 500 m² di pinggir jalan raya dengan lalu lintas ramai, sangat cocok untuk usaha seperti ruko, kafe, atau gudang. Sertifikat SHM dan siap balik nama.', 'Lingkungan sudah berkembang dengan permukiman di sekitarnya. Akses mudah dari berbagai arah dan potensi kenaikan nilai yang tinggi.']::text[], array['SHM', 'Pinggir jalan raya', 'Cocok usaha']::text[], '{"road":true,"pay":"cash","build":"","reno":false,"facing":"Utara","floors":0,"ipl":null,"avail":[],"sec":[],"fac":["ibadah","minimarket"],"near":["2 km","10 km","3 km","40 km"],"walk":2,"lv":"verified","pbb":"Lunas 2026","imb":"Tidak diperlukan (tanah kosong)","isNew":false,"dev":""}'::jsonb),
  (9, 'rumah-hook-taman-luas-cibubur-jakarta-timur', 'tayang', false, 'rumah', 'Dijual', 'Rumah Hook Taman Luas', 'Cibubur, Jakarta Timur', 'Jakarta Timur', 2400000000, 'Rp 2,4 M', '', 160, 180, 4, '160 m²', '180 m²', '4', '3', 'HGB', -6.362, 106.884, array['/assets/83c967883699f4f4515045d52e7d9128.jpg', '/assets/a3d3de7f4f80512034b449f86313effd.jpg', '/assets/0015fe3ee9f7d9fae5966c1354805c8c.jpg']::text[], array['Rumah posisi hook dengan taman samping yang luas, cocok untuk keluarga besar. Desain modern tropis dengan plafon tinggi dan sirkulasi udara yang baik.', 'Empat kamar tidur, tiga kamar mandi, ruang kerja, dan carport untuk dua mobil. Dekat sekolah internasional dan akses tol.']::text[], array['Taman luas', 'Carport 2 mobil', 'Posisi hook']::text[], '{"pay":"kpr","build":"inden","reno":false,"facing":"Timur Laut","floors":2,"ipl":null,"avail":["taman","garasi","balkon","gudang"],"sec":["onegate","cctv","security"],"fac":["gym","pool","clubhouse","jogging","ibadah","playground","minimarket","parkir"],"near":["2 km","18 km","3 km","45 km"],"walk":2,"lv":"proses","pbb":"Dalam pemecahan","imb":"Ada (PBG)","isNew":true,"dev":"Terverifikasi agen Vinmel"}'::jsonb),
