  (11, 'apartemen-3br-untuk-keluarga-kemayoran-jakarta-pusat', 'tayang', false, 'apartemen', 'Dijual', 'Apartemen 3BR untuk Keluarga', 'Kemayoran, Jakarta Pusat', 'Jakarta Pusat', 2800000000, 'Rp 2,8 M', '', 0, 98, 3, '—', '98 m²', '3', '2', 'Strata', -6.161, 106.85, array['/assets/1e906c61051aeefbecc56d6a933ff29d.jpg', '/assets/48a0c6593a8eb95a0e54c71d29f7ac5b.jpg', '/assets/a797bc56b381b796263a2b0f1fa0f874.jpg']::text[], array['Unit tiga kamar tidur yang lapang untuk keluarga, dengan balkon dan pemandangan taman kota.', 'Kompleks apartemen dengan kolam renang, taman bermain, dan parkir basement. Dekat area bisnis dan rumah sakit.']::text[], array['Kolam renang', 'Taman bermain', 'Parkir basement']::text[], '{"unitType":"Suite","pay":"kpr","build":"inden","reno":false,"facing":"Utara","floors":0,"ipl":["gratis","","2"],"avail":["balkon","gudang"],"sec":["onegate","cctv","security"],"fac":["gym","pool","clubhouse","jogging","ibadah","playground","minimarket","parkir"],"near":["1 km","4 km","2 km","20 km"],"walk":3,"lv":"proses","pbb":"Belum terbit (unit inden)","imb":"Ada (PBG)","isNew":true,"dev":"Dalam pengecekan agen Vinmel"}'::jsonb),
